// Escape text before it goes into HTML (e.g. map popups) so a name can never run as markup.
function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// ── ACCESSIBILITY HELPERS ─────────────────────────────────────────────────────
// Dialog behaviour for the full-screen overlays: move focus in when one opens, keep Tab inside it,
// and hand focus back to whatever opened it when it closes.
function useDialog(ref, onEscape) {
  useEffect(() => {
    const node = ref.current;
    if (!node) return undefined;
    const opener = document.activeElement;
    const focusables = () => [...node.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')]
      .filter(e => e.getClientRects().length > 0);
    node.focus();
    const onKey = e => {
      if (e.key === 'Escape' && onEscape) { onEscape(); return; }
      if (e.key !== 'Tab') return;
      const f = focusables();
      if (!f.length) { e.preventDefault(); return; }
      const first = f[0], last = f[f.length - 1], active = document.activeElement;
      if (e.shiftKey && (active === first || active === node)) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && active === last) { e.preventDefault(); first.focus(); }
    };
    node.addEventListener('keydown', onKey);
    return () => { node.removeEventListener('keydown', onKey); if (opener && typeof opener.focus === 'function') opener.focus(); };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
}

