// ── OFFLINE QUEUE HELPERS ─────────────────────────────────────────────────────

const QUEUE_KEY = 'sqm_pending_queue';

function queueLoad() {
  try { return JSON.parse(localStorage.getItem(QUEUE_KEY) || '[]'); } catch { return []; }
}

function queueSave(items) {
  try { localStorage.setItem(QUEUE_KEY, JSON.stringify(items)); } catch {}
}

function queueAdd(payload) {
  const q = queueLoad();
  q.push({ ...payload, _queuedAt: new Date().toISOString() });
  queueSave(q);
}

function queueRemove(index) {
  const q = queueLoad();
  q.splice(index, 1);
  queueSave(q);
}

async function queueFlush(onProgress) {
  const q = queueLoad();
  if (!q.length) return { sent: 0, failed: 0 };
  let sent = 0, failed = 0;
  for (let i = q.length - 1; i >= 0; i--) {
    try {
      await fetch(APPS_SCRIPT_URL, {
        method: 'POST', mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(q[i]),
      });
      queueRemove(i);
      sent++;
    } catch {
      failed++;
    }
    if (onProgress) onProgress(sent, failed);
  }
  return { sent, failed };
}

